import type { Register } from 'claude-code'

import { formatMavenLine, linkJiraKeys, splitReply, summarizeMaven } from './format'

export const register: Register = (on, options) => {
  const jiraBaseUrl = String(options.jiraBaseUrl ?? 'https://nordnetbank.atlassian.net')
  const jiraProjects = String(options.jiraProjects ?? 'ASB')
    .split(',')
    .map(p => p.trim().toUpperCase())
    .filter(p => /^[A-Z][A-Z0-9]+$/.test(p))

  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    if (e.props.isSummary) return next(e)

    const reply = splitReply(e.props.text)
    const body = linkJiraKeys(reply.body, jiraBaseUrl, jiraProjects)
    if (!reply.result && !reply.next) {
      return body === e.props.text ? next(e) : next({ ...e, props: { ...e.props, text: body } })
    }

    const { Box, Text } = $.ui.resolve(e)
    const drawnBody = body === '' ? null : await next({ ...e, props: { ...e.props, text: body } })
    return (
      <Box flexDirection="column">
        {reply.result && (
          <Text bold color={reply.result.status}>
            {reply.result.line}
          </Text>
        )}
        {drawnBody}
        {reply.next && (
          <Box marginTop={1}>
            <Text dimColor>→ {reply.next}</Text>
          </Box>
        )}
      </Box>
    )
  })

  on('ui.render', { component: 'ToolResult', props: { tool: 'Bash' } }, ($, e, next) => {
    const summary = summarizeMaven(bashOutputText(e.props.output))
    if (!summary) return next(e)

    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        <Text bold color={summary.isSuccess ? 'success' : 'error'}>
          {formatMavenLine(summary)}
        </Text>
        {summary.problems.map((problem, i) => (
          <Text key={String(i)} color="error">
            {'  '}• {problem}
          </Text>
        ))}
      </Box>
    )
  })
}

// A non-zero exit (a failed build) stores the error text as a string, not the { stdout, stderr } record.
function bashOutputText(output: unknown): string {
  if (typeof output === 'string') return output
  const record = output as { stdout?: string; stderr?: string } | undefined
  return `${record?.stdout ?? ''}\n${record?.stderr ?? ''}`
}

