export type Status = 'success' | 'warning' | 'error' | 'suggestion'

const MARKERS: ReadonlyArray<readonly [string, Status]> = [
  ['✅', 'success'],
  ['⚠️', 'warning'],
  ['❌', 'error'],
  ['❓', 'suggestion'],
]

export type SplitReply = {
  result?: { line: string; status: Status }
  body: string
  next?: string
}

export function splitReply(text: string): SplitReply {
  const lines = text.split('\n')
  const first = lines[0]?.trim() ?? ''
  const marker = MARKERS.find(([glyph]) => first.startsWith(glyph))
  const result = marker ? { line: first, status: marker[1] } : undefined
  if (result) lines.shift()

  let next: string | undefined
  const lastIndex = findLastNonBlank(lines)
  if (lastIndex >= 0 && /^\**Next\**:/.test(lines[lastIndex]!.trim())) {
    next = lines[lastIndex]!.trim().replace(/^\**Next\**:\s*/, '')
    lines.splice(lastIndex, 1)
  }

  return { result, body: lines.join('\n').trim(), next }
}

function findLastNonBlank(lines: readonly string[]): number {
  for (let i = lines.length - 1; i >= 0; i--) {
    if (lines[i]!.trim() !== '') return i
  }
  return -1
}

// Skips fenced blocks, inline code and existing markdown links so only bare keys become links.
export function linkJiraKeys(text: string, baseUrl: string, projects: readonly string[]): string {
  if (projects.length === 0) return text
  const key = new RegExp(`(?<![\\w/\\[-])((?:${projects.join('|')})-\\d+)(?![\\w\\]])`, 'g')
  const base = baseUrl.replace(/\/+$/, '')
  return text
    .split(/(```[\s\S]*?```|`[^`\n]*`|\[[^\]\n]*\]\([^)\n]*\))/)
    .map((part, i) => (i % 2 === 1 ? part : part.replace(key, `[$1](${base}/browse/$1)`)))
    .join('')
}

export type MavenSummary = {
  isSuccess: boolean
  tests?: { run: number; failures: number; errors: number; skipped: number }
  time?: string
  problems: string[]
}

const MAX_PROBLEMS = 10

export function summarizeMaven(output: string): MavenSummary | undefined {
  const outcome = output.match(/BUILD (SUCCESS|FAILURE)/)
  if (!outcome) return undefined

  const totals = [...output.matchAll(/Tests run: (\d+), Failures: (\d+), Errors: (\d+), Skipped: (\d+)(?!,)/g)].at(-1)
  const time = output.match(/Total time:\s+([^\n]+)/)?.[1]?.trim()
  const problems = [
    ...output.matchAll(/^\[ERROR\]\s+(?:Failures|Errors):\s*$|^\[ERROR\]\s{2,}(\S.*)$/gm),
  ]
    .map(m => m[1])
    .filter((line): line is string => line !== undefined)
  const compileErrors = [...output.matchAll(/^\[ERROR\] (\/\S+\.java:\[\d+,\d+\] .+)$/gm)].map(m => m[1]!)

  return {
    isSuccess: outcome[1] === 'SUCCESS',
    tests: totals
      ? { run: Number(totals[1]), failures: Number(totals[2]), errors: Number(totals[3]), skipped: Number(totals[4]) }
      : undefined,
    time,
    problems: [...new Set([...problems, ...compileErrors])].slice(0, MAX_PROBLEMS),
  }
}

export function formatMavenLine(summary: MavenSummary): string {
  const parts = [summary.isSuccess ? '✅ BUILD SUCCESS' : '❌ BUILD FAILURE']
  const t = summary.tests
  if (t) {
    const failed = t.failures + t.errors
    parts.push(failed > 0 ? `${failed}/${t.run} tests failed` : `${t.run} tests`)
    if (t.skipped > 0) parts.push(`${t.skipped} skipped`)
  }
  if (summary.time) parts.push(summary.time)
  return parts.join(' · ')
}

